import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    k = int(data[1])

    if n == 0:
        print()
        return

    arr = list(map(int, data[2:2+n]))

    arr.sort()

    if k >= n - 1:
        result = arr
    elif k < 0:
        result = arr[::-1]
    else:
        first_part = arr[:k+1]
        second_part = arr[k+1:][::-1]
        result = first_part + second_part

    print(' '.join(map(str, result)))

if __name__ == "__main__":
    main()
